asil.pseudocode:
def asil(s, e, c):
    # s: 0~3, e: 0~4, c: 0~3 (ISO 26262 Part 3)
    if s == 0 or e == 0 or c == 0:
        return 'QM'  # 안전 요구 없음
    total = s + e + c  # 표의 규칙성: 합으로 결정
    if total == 10:
        return 'D'  # S3·E4·C3
    if total == 9:
        return 'C'
    if total == 8:
        return 'B'
    if total == 7:
        return 'A'
    return 'QM'  # 합 6 이하
